/*
 * Binary data sections and string/data carrier for eac.elf.
 *
 * This preserves allocatable non-executable ELF section bytes plus
 * the VM dispatch table embedded in .text, so the all-evidence C
 * artifact carries program data as well as reconstructed code.
 * String rows carry full escaped text and a pointer into the exact
 * backing section byte array, not just a shortened preview.
 */
#include <stdint.h>
#include <stddef.h>

typedef struct VMBinaryDataSection {
    const char *name;
    uint16_t section_index;
    uint32_t type;
    uint64_t flags;
    uint64_t vaddr;
    uint64_t file_offset;
    uint64_t size;
    uint64_t entsize;
    const uint8_t *bytes;
} VMBinaryDataSection;

typedef struct VMBinaryStringRef {
    uint16_t data_section_index;
    uint64_t section_offset;
    uint64_t vaddr;
    uint64_t length;
    const uint8_t *bytes;
    const char *text;
} VMBinaryStringRef;

